import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Database Basics — Quick Reference","description":"","frontmatter":{},"headers":[],"relativePath":"todo/my_verify_docs/db-basics.md","filePath":"todo/my_verify_docs/db-basics.md"}'),i={name:"todo/my_verify_docs/db-basics.md"};function n(r,e,l,c,d,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="database-basics-—-quick-reference" tabindex="-1">Database Basics — Quick Reference <a class="header-anchor" href="#database-basics-—-quick-reference" aria-label="Permalink to &quot;Database Basics — Quick Reference&quot;">​</a></h1><p>A small primer of foundational concepts worth knowing. Each section is intentionally short — use it as a map for what to read deeper into.</p><hr><h2 id="surrogate-key-vs-natural-key" tabindex="-1">Surrogate Key vs Natural Key <a class="header-anchor" href="#surrogate-key-vs-natural-key" aria-label="Permalink to &quot;Surrogate Key vs Natural Key&quot;">​</a></h2><p><strong>Surrogate key</strong> — an artificial identifier with no business meaning (auto-increment <code>id</code>, UUID). Generated by the system purely to uniquely identify a row.</p><p><strong>Natural key</strong> — a column (or set of columns) that already exists in the business domain and uniquely identifies a row (e.g., <code>email</code>, <code>ssn</code>, <code>isbn</code>, <code>(country_code, tax_id)</code>).</p><h3 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Surrogate</th><th>Natural</th></tr></thead><tbody><tr><td>Source</td><td>System-generated</td><td>Business data</td></tr><tr><td>Meaning</td><td>None</td><td>Domain meaningful</td></tr><tr><td>Stability</td><td>Never changes</td><td>Can change (emails, names, codes)</td></tr><tr><td>Size</td><td>Small, uniform (BIGINT/UUID)</td><td>Variable, often larger</td></tr><tr><td>Joins</td><td>Fast, single column</td><td>Can be composite/wide</td></tr><tr><td>Privacy</td><td>Safe to expose</td><td>May leak PII (SSN, email)</td></tr><tr><td>Uniqueness guarantee</td><td>Always</td><td>Depends on real-world rules</td></tr></tbody></table><h3 id="when-to-prefer-surrogate" tabindex="-1">When to prefer surrogate <a class="header-anchor" href="#when-to-prefer-surrogate" aria-label="Permalink to &quot;When to prefer surrogate&quot;">​</a></h3><ul><li>Most OLTP tables — default choice</li><li>Natural key is mutable (email, username)</li><li>Natural key is composite or wide</li><li>Natural key is sensitive (don&#39;t use SSN as FK everywhere)</li><li>You need a stable external/URL identifier</li></ul><h3 id="when-natural-keys-are-fine" tabindex="-1">When natural keys are fine <a class="header-anchor" href="#when-natural-keys-are-fine" aria-label="Permalink to &quot;When natural keys are fine&quot;">​</a></h3><ul><li>Truly immutable, well-governed values (ISO country code, currency code)</li><li>Lookup/reference tables where the code IS the data (<code>USD</code>, <code>EUR</code>)</li><li>Junction tables where the composite of two FKs is naturally unique</li></ul><h3 id="common-practice-—-use-both" tabindex="-1">Common practice — use both <a class="header-anchor" href="#common-practice-—-use-both" aria-label="Permalink to &quot;Common practice — use both&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id         </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BIGSERIAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> PRIMARY KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- surrogate</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  email      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UNIQUE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- natural, enforced</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  created_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TIMESTAMPTZ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h3><ul><li>Surrogate alone (no unique on natural key) → duplicates sneak in</li><li>Natural key as FK everywhere → painful cascading updates when it changes</li><li>Random UUIDs as clustered PK → index fragmentation; prefer UUIDv7/ULID</li></ul><hr><h2 id="other-basics-to-read-about" tabindex="-1">Other Basics to Read About <a class="header-anchor" href="#other-basics-to-read-about" aria-label="Permalink to &quot;Other Basics to Read About&quot;">​</a></h2><h3 id="schema-design" tabindex="-1">Schema design <a class="header-anchor" href="#schema-design" aria-label="Permalink to &quot;Schema design&quot;">​</a></h3><ul><li><strong>Normalization (1NF → BCNF)</strong> — eliminating redundancy via functional dependencies; know up to 3NF in practice.</li><li><strong>Denormalization</strong> — deliberate redundancy for read performance; trade-off against write/consistency cost.</li><li><strong>Constraints</strong> — <code>PRIMARY KEY</code>, <code>FOREIGN KEY</code>, <code>UNIQUE</code>, <code>CHECK</code>, <code>NOT NULL</code>; let the DB enforce invariants, not the app.</li><li><strong>Soft delete vs hard delete</strong> — <code>deleted_at</code> column vs actual <code>DELETE</code>; affects FKs, uniqueness, and queries.</li><li><strong>Data types</strong> — <code>TEXT</code> vs <code>VARCHAR(n)</code>, <code>NUMERIC</code>/<code>DECIMAL</code> vs <code>FLOAT</code> (always exact types for money), <code>JSON</code> vs <code>JSONB</code>, ENUM vs lookup table, <code>TIMESTAMPTZ</code> vs <code>TIMESTAMP</code>.</li><li><strong>Foreign key behaviors</strong> — <code>ON DELETE CASCADE</code> / <code>SET NULL</code> / <code>RESTRICT</code> / <code>NO ACTION</code>; deferred constraints (<code>DEFERRABLE INITIALLY DEFERRED</code>) for circular FK setups.</li><li><strong>Index your foreign keys</strong> — most engines don&#39;t auto-index FK columns; lookups, joins, and cascading deletes get slow without one.</li><li><strong>Identity columns / sequences</strong> — <code>BIGSERIAL</code> vs <code>GENERATED ... AS IDENTITY</code>; sequence semantics under rollback (gaps are normal); UUIDv7 / ULID for distributed IDs.</li></ul><h3 id="transactions-consistency" tabindex="-1">Transactions &amp; consistency <a class="header-anchor" href="#transactions-consistency" aria-label="Permalink to &quot;Transactions &amp; consistency&quot;">​</a></h3><ul><li><strong>ACID</strong> — Atomicity, Consistency, Isolation, Durability.</li><li><strong>Isolation levels</strong> — Read Uncommitted / Read Committed / Repeatable Read / Serializable; understand dirty reads, non-repeatable reads, phantom reads.</li><li><strong>Locking</strong> — pessimistic (<code>SELECT ... FOR UPDATE</code>) vs optimistic (version columns / CAS).</li><li><strong>Deadlocks</strong> — what causes them, how to order locks consistently to avoid them.</li><li><strong>Idempotency</strong> — designing writes that can be safely retried (idempotency keys, upserts).</li><li><strong>MVCC (multi-version concurrency control)</strong> — readers don&#39;t block writers; the engine keeps old row versions until no transaction still needs them. Underpins how Postgres / Oracle / InnoDB actually implement isolation.</li><li><strong>Upserts</strong> — <code>INSERT ... ON CONFLICT DO UPDATE</code> (Postgres), <code>MERGE</code> (SQL standard), <code>INSERT ... ON DUPLICATE KEY UPDATE</code> (MySQL); the practical tool for idempotent writes.</li><li><strong>Two-phase commit / XA</strong> — distributed transactions across resource managers; brittle and slow, mostly replaced by saga / outbox patterns.</li><li><strong>Read-your-own-writes</strong> — under read replicas, a client may read stale data right after writing. Solved with primary-pinning for a window, session affinity, or causal-consistency tokens.</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li><strong>Indexes</strong> — B-tree, hash, GIN/GiST; composite indexes and column order; covering indexes.</li><li><strong>Query plans</strong> — <code>EXPLAIN</code> / <code>EXPLAIN ANALYZE</code>; spotting seq scans, nested loops, hash joins.</li><li><strong>N+1 query problem</strong> — classic ORM pitfall; fix with joins, batching, or <code>IN</code> queries.</li><li><strong>Connection pooling</strong> — why opening a new connection per request kills you (HikariCP, PgBouncer).</li><li><strong>Pagination</strong> — offset vs keyset (cursor) pagination; why <code>OFFSET</code> is slow at scale.</li><li><strong>Prepared statements &amp; plan cache</strong> — server-side parse + plan reuse; drivers also use them as the SQL-injection defense and the batching unit (e.g., <code>reWriteBatchedInserts</code> in PG JDBC).</li><li><strong>VACUUM / autovacuum / bloat (Postgres)</strong> — MVCC leaves dead tuples behind; <code>VACUUM</code> reclaims them. Bloat = unreclaimed dead space inflating tables/indexes; freeze + transaction-id wraparound is a separate operational worry.</li><li><strong>Pool sizing &amp; connection lifecycle</strong> — pool size ≠ thread count; connections are heavy. PgBouncer pooling modes (session / transaction / statement) and what each forbids (e.g., transaction-mode breaks server-side prepared statements without care).</li><li><strong>Hot rows / lock contention</strong> — concentrated writes on the same row serialize the system; mitigations: sharding the counter, queueing updates, optimistic locking, deferred materialization.</li></ul><h3 id="joins-queries" tabindex="-1">Joins &amp; queries <a class="header-anchor" href="#joins-queries" aria-label="Permalink to &quot;Joins &amp; queries&quot;">​</a></h3><ul><li><strong>Join types</strong> — INNER, LEFT/RIGHT OUTER, FULL, CROSS; semi/anti joins via <code>EXISTS</code>/<code>NOT EXISTS</code>.</li><li><strong>Aggregations</strong> — <code>GROUP BY</code>, <code>HAVING</code> vs <code>WHERE</code>.</li><li><strong>Window functions</strong> — <code>ROW_NUMBER</code>, <code>RANK</code>, <code>LAG</code>/<code>LEAD</code>, running totals.</li><li><strong>CTEs</strong> — <code>WITH</code> clauses; recursive CTEs for trees/graphs.</li><li><strong>NULL semantics (three-valued logic)</strong> — <code>NULL = NULL</code> is <code>UNKNOWN</code>, not <code>TRUE</code>. <code>NOT IN (subquery with any NULL)</code> returns nothing. Use <code>IS [NOT] DISTINCT FROM</code> for NULL-safe equality, and watch out in <code>WHERE</code>, <code>CHECK</code>, and unique-constraint behavior.</li><li><strong>Bulk loads &amp; batch writes</strong> — <code>COPY</code> (Postgres) / <code>LOAD DATA</code> (MySQL) for large imports; batched <code>INSERT</code> with <code>RETURNING</code> for app-level throughput; statement-level vs row-level triggers behave very differently here.</li><li><strong>Set-based vs row-by-row</strong> — the most common SQL anti-pattern is looping in app code where one statement would do. Learn to express problems as joins, window functions, or <code>INSERT ... SELECT</code>.</li></ul><h3 id="distributed-data" tabindex="-1">Distributed data <a class="header-anchor" href="#distributed-data" aria-label="Permalink to &quot;Distributed data&quot;">​</a></h3><ul><li><strong>CAP theorem</strong> — Consistency, Availability, Partition tolerance — pick two under partition.</li><li><strong>Replication</strong> — primary/replica, sync vs async, replica lag.</li><li><strong>Sharding / partitioning</strong> — horizontal split by key; range vs hash; cross-shard queries are expensive.</li><li><strong>Eventual consistency</strong> — what it means and when it&#39;s acceptable.</li><li><strong>OLTP vs OLAP</strong> — transactional (row-store) vs analytical (column-store) workloads.</li><li><strong>Read replica routing / read-write split</strong> — easy to set up, the trap is replica lag. Decide explicitly per query: is stale-read OK, or does this need primary?</li><li><strong>Outbox pattern</strong> — write the domain change and an <code>outbox_events</code> row in the same DB transaction; a separate publisher reads the outbox and ships events to Kafka/etc. Solves dual-write inconsistency.</li><li><strong>CDC (Change Data Capture)</strong> — Debezium / logical replication stream row-level changes out of the DB without polling; basis for cache invalidation, search index sync, event-driven downstream systems.</li><li><strong>Saga pattern</strong> — long-running multi-service workflows broken into local transactions with compensating actions; replaces XA where eventual consistency is acceptable.</li><li><strong>Time zones at scale</strong> — <code>TIMESTAMPTZ</code> stores UTC and renders in session TZ; <code>TIMESTAMP</code> doesn&#39;t store the zone at all. Default to TZ-aware columns and store UTC end-to-end; convert at the edges only.</li><li><strong>Clock skew &amp; ordering</strong> — distributed systems can&#39;t trust wall-clock ordering; learn about logical clocks (Lamport, vector clocks) and where hybrid logical clocks (HLC) show up.</li></ul><h3 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h3><ul><li><strong>Migrations</strong> — versioned schema changes (Flyway, Liquibase); forward-only vs reversible.</li><li><strong>Backups &amp; PITR</strong> — full + WAL/binlog for point-in-time recovery.</li><li><strong>Online schema changes</strong> — adding columns / indexes without locking large tables (<code>CREATE INDEX CONCURRENTLY</code>, pt-online-schema-change).</li><li><strong>Observability</strong> — slow query log, <code>pg_stat_statements</code>, lock waits, <code>pg_stat_activity</code>, blocked-by chains.</li><li><strong>Expand-contract / parallel change</strong> — zero-downtime schema evolution: (1) add new column/table, (2) dual-write, (3) backfill, (4) switch reads, (5) drop old. The fix for &quot;the app and schema can never deploy atomically&quot;.</li><li><strong>Backup types &amp; restore drills</strong> — logical (<code>pg_dump</code>, <code>mysqldump</code>) vs physical (<code>pg_basebackup</code>, snapshots); always test restores — an untested backup isn&#39;t a backup.</li><li><strong>Failover &amp; promotion</strong> — synchronous vs asynchronous replicas, RPO/RTO, what &quot;split-brain&quot; looks like, why a managed DB&#39;s failover is rarely zero-downtime for the app.</li></ul><h3 id="nosql-beyond" tabindex="-1">NoSQL &amp; beyond <a class="header-anchor" href="#nosql-beyond" aria-label="Permalink to &quot;NoSQL &amp; beyond&quot;">​</a></h3><ul><li><strong>Document stores</strong> (MongoDB), <strong>key-value</strong> (Redis, DynamoDB), <strong>wide-column</strong> (Cassandra), <strong>search</strong> (Elasticsearch), <strong>graph</strong> (Neo4j) — pick by access pattern, not hype.</li><li><strong>Cache strategies</strong> — read-through, write-through, write-behind, cache-aside; invalidation is the hard part.</li><li><strong>Specialized engines / extensions</strong> — full-text search (<code>tsvector</code> + GIN, or push to Elasticsearch), geospatial (PostGIS + GiST), time-series (TimescaleDB hypertables), vectors (<code>pgvector</code> + HNSW/IVF for embeddings).</li><li><strong>DB-as-a-queue</strong> — using a table with <code>FOR UPDATE SKIP LOCKED</code> as a poor-man&#39;s queue is fine for low volume; turns into pain at scale (polling, lock contention, no fan-out). Know when to graduate to Kafka / SQS.</li></ul><h3 id="security-multi-tenancy" tabindex="-1">Security &amp; multi-tenancy <a class="header-anchor" href="#security-multi-tenancy" aria-label="Permalink to &quot;Security &amp; multi-tenancy&quot;">​</a></h3><ul><li><strong>SQL injection</strong> — the only defense is parameterized queries / bound parameters. Never concatenate user input into SQL. ORMs help, but raw query escape hatches reintroduce the risk — audit those carefully.</li><li><strong>Row-level security (RLS)</strong> — Postgres feature: enforce per-tenant / per-user filters at the engine layer, so a missed <code>WHERE tenant_id = ?</code> in app code can&#39;t leak rows.</li><li><strong>Multi-tenancy patterns</strong> — schema-per-tenant vs shared schema with <code>tenant_id</code> vs database-per-tenant; trade isolation, blast radius, ops cost, and &quot;noisy neighbour&quot; risk.</li><li><strong>Encryption</strong> — at rest (TDE / disk-level / column-level for PII) and in transit (TLS to DB). Column-level encryption matters when &quot;DB compromise&quot; is in your threat model.</li><li><strong>Auditing &amp; history tables</strong> — temporal/system-versioned tables, append-only event tables, or trigger-based shadow tables; &quot;who changed what when&quot; is a recurring compliance + debugging need.</li><li><strong>Least privilege at the DB</strong> — separate roles for app / migrations / readonly / ops; revoke <code>SUPERUSER</code> from app users; explicit <code>GRANT</code>s on schema and table level.</li></ul><h3 id="application-side-patterns" tabindex="-1">Application-side patterns <a class="header-anchor" href="#application-side-patterns" aria-label="Permalink to &quot;Application-side patterns&quot;">​</a></h3><ul><li><strong>Repository / DAO</strong> vs <strong>active record</strong> — where query logic lives, and how testable each style is.</li><li><strong>Unit of Work</strong> — flushing many changes as one transaction at the request boundary (JPA <code>EntityManager</code>, SQLAlchemy session).</li><li><strong>Optimistic locking via <code>@Version</code></strong> — concurrent writes detected at commit; pairs naturally with REST PUT/<code>If-Match</code>.</li><li><strong>Materialized views &amp; cached aggregates</strong> — when read-heavy reports outpace the OLTP path; refresh strategies (on demand, scheduled, incremental).</li><li><strong>Don&#39;t trust the app for invariants</strong> — unique, FK, check, and NOT NULL constraints in the DB are non-negotiable; app-only validation is racy.</li></ul><hr><h2 id="recommended-reading" tabindex="-1">Recommended reading <a class="header-anchor" href="#recommended-reading" aria-label="Permalink to &quot;Recommended reading&quot;">​</a></h2><ul><li><em>Designing Data-Intensive Applications</em> — Martin Kleppmann (the canonical book)</li><li><em>Database Internals</em> — Alex Petrov (how storage engines actually work)</li><li><em>SQL Performance Explained</em> — Markus Winand (also <a href="https://use-the-index-luke.com" target="_blank" rel="noreferrer">https://use-the-index-luke.com</a>)</li><li>PostgreSQL docs — chapters on MVCC, indexes, and query planning</li></ul>`,39)])])}const p=t(i,[["render",n]]);export{g as __pageData,p as default};
